using Godot;
using System;
using System.Collections.Generic;

public partial class TransformationWorkspaceOperations
{
    private static T Attach<T>(Node parent,T child) where T:Node{parent.AddChild(child);return child;}
    private static Label Caption(Node parent,string text){var result=Attach(parent,new Label {Text=text});result.AddThemeColorOverride("font_color",new Color("80dcca"));return result;}
    private static Button Action(Node parent,string text,Action callback,string hint=""){var result=Attach(parent,new Button {Text=text,TooltipText=hint,CustomMinimumSize=new Vector2(0,28)});result.Pressed+=callback;return result;}
    private static void Clear(Node parent){foreach(Node child in parent.GetChildren()){parent.RemoveChild(child);child.QueueFree();}}
    private static OptionButton Choice(Node parent,IReadOnlyList<string> options,string current,Action<string> callback){var result=new OptionButton {ClipText=true,CustomMinimumSize=new Vector2(100,0),SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};int selected=0;for(int index=0;index<options.Count;index++){result.AddItem(options[index]);if(options[index]==current)selected=index;}result.Select(selected);parent.AddChild(result);result.ItemSelected+=index=>callback(result.GetItemText((int)index));return result;}
    private Godot.Range NumberControl(Control owner,Node parent,string caption,double value,double minimum,double maximum,double step,Action<double> setter,bool stateEdit=false,bool undoable=true)
    {
        var column=Attach(parent,new VBoxContainer {SizeFlagsHorizontal=Control.SizeFlags.ExpandFill});Caption(column,caption).AddThemeFontSizeOverride("font_size",10);var number=new DragNumber();number.MinValue=minimum;number.MaxValue=maximum;number.Step=step;number.Value=value;var primary=Session(owner).Call("primary").As<Resource>();number.Set("editable",!(stateEdit&&(Flag(owner,"previewing")||(primary!=null&&primary.Get("locked").AsBool()))));column.AddChild(number);double lastValid=value;
        number.Connect("interaction_started",Callable.From(()=>{finish_pending(owner);if(undoable)Session(owner).Call("begin");number.SetMeta("transformation_drag",true);owner.Set("_number_drag",true);}));
        number.Connect("interaction_ended",Callable.From(()=>{if(!number.GetMeta("transformation_drag",false).AsBool())return;number.SetMeta("transformation_drag",false);owner.Set("_number_drag",false);if(undoable)owner.CallDeferred("_finish_number_transaction",Session(owner));}));
        number.Connect("preview_changed",Callable.From<double>(next=>{setter(next);owner.Set("_render_pending",true);}));
        number.Connect("drag_committed",Callable.From<double>(next=>{owner.Set("_number_drag",false);if(undoable){if(commit_number(owner,caption,stateEdit))lastValid=number.Value;else number.SetValueNoSignal(lastValid);}}));
        number.Connect("drag_cancelled",Callable.From(()=>{owner.Set("_number_drag",false);if(undoable)Session(owner).Call("cancel");else{setter(number.Value);owner.Set("_render_pending",true);}}));
        number.ValueChanged+=next=>{if(Flag(owner,"_syncing")||number.Get("dragging").AsBool())return;if(undoable)Session(owner).Call("begin");setter(next);owner.Set("_render_pending",true);if(undoable){if(commit_number(owner,caption,stateEdit))lastValid=number.Value;else number.SetValueNoSignal(lastValid);}};return number;
    }
    public bool commit_number(Control owner,string caption,bool stateEdit){var errors=Document(owner).Call("validate").AsStringArray();if(errors.Length>0){Session(owner).Call("cancel");Item<Label>(owner,"status").Text=errors[0];return false;}if(stateEdit)touch_states(owner);Session(owner).Call("commit","Change "+caption);return true;}
    public void finish_number_transaction(Control owner,RefCounted session){if(Session(owner)==session&&!Flag(owner,"_gesture")&&!Flag(owner,"_number_drag")&&Item<Control>(owner,"timeline").Get("drag").AsString().Length==0&&session.Get("pending").AsGodotDictionary().Count>0)session.Call("cancel");}
    public void refresh_properties(Control owner)
    {
        var panel=Item<VBoxContainer>(owner,"properties");Clear(panel);var session=Session(owner);var item=session.Call("primary").As<Resource>();var state=Active(owner);if(item==null||state==null)return;Caption(panel,Flag(owner,"previewing")?"STATE · CHOOSE TO EDIT":"STATE DEFINITION");var picker=new OptionButton {SizeFlagsHorizontal=Control.SizeFlags.ExpandFill,ClipText=true};picker.AddThemeConstantOverride("icon_max_width",36);var states=item.Get("states").AsGodotArray();foreach(var raw in states){var candidate=raw.As<Resource>();picker.AddIconItem(candidate.Get("artwork").AsGodotObject().Get("texture").As<Texture2D>(),candidate.Get("title").AsString());picker.GetPopup().SetItemIconMaxWidth(picker.ItemCount-1,24);}picker.Select(states.IndexOf(state));panel.AddChild(picker);picker.ItemSelected+=index=>{finish_pending(owner);session.Get("edit_states").AsGodotDictionary()[item.Get("id")]=states[(int)index].AsGodotObject().Get("id");session.Set("pixel_mask",default(Variant));session.Get("pixel_reference").AsGodotDictionary().Clear();Item<Control>(owner,"canvas").Set("selection",default(Variant));Item<Control>(owner,"canvas").Set("selection_texture",default(Variant));edit_mode(owner);};var row=Attach(panel,new HBoxContainer());Action(row,"＋ State",()=>{finish_pending(owner);edit_mode(owner);session.Call("add_state",false);},"Create a new state from this drawing; later painting is independent");Action(row,"＋ Blank",()=>{finish_pending(owner);edit_mode(owner);session.Call("add_state",true);});Action(row,"⋯",()=>owner.Call("state_menu"));var name=Attach(panel,new LineEdit {Text=state.Get("title").AsString(),PlaceholderText="State name",Editable=!item.Get("locked").AsBool()});owner.Set("_state_name",name);name.TextSubmitted+=value=>{if(!item.Get("locked").AsBool()&&value.Trim().Length>0){session.Call("begin");state.Set("title",value.Trim());session.Call("commit","Rename state");}};
        var artwork=state.Get("artwork").AsGodotObject();var baseSize=item.Get("base_size").AsVector2();foreach(string kind in new[]{"Position","Scale","Pivot"}){row=Attach(panel,new HBoxContainer());var vector=kind=="Position"?artwork.Get("position").AsVector2():kind=="Scale"?artwork.Get("dimensions").AsVector2()/baseSize:state.Get("pivot").AsVector2();for(int index=0;index<2;index++){int axis=index;NumberControl(owner,row,kind+" "+new[]{"X","Y"}[axis],vector[axis],kind=="Scale"?.01:kind=="Pivot"?0:-100000,kind=="Scale"?64:kind=="Pivot"?1:100000,.01,next=>{if(kind=="Pivot"){var pivot=state.Get("pivot").AsVector2();pivot[axis]=(float)next;state.Set("pivot",pivot);Item<Control>(owner,"canvas").Set("pivot_uv",pivot);}else{string field=kind=="Position"?"position":"dimensions";var value=artwork.Get(field).AsVector2();value[axis]=(float)next*(kind=="Scale"?baseSize[axis]:1);artwork.Set(field,value);}},true);}}
        row=Attach(panel,new HBoxContainer());NumberControl(owner,row,"Rotation °",Mathf.RadToDeg(artwork.Get("rotation").AsDouble()),-36000,36000,.1,next=>artwork.Set("rotation",Mathf.DegToRad(next)),true);NumberControl(owner,row,"Opacity",artwork.Get("opacity").AsDouble(),0,1,.01,next=>artwork.Set("opacity",next),true);var visible=Attach(panel,new CheckButton {Text="State visible",ButtonPressed=artwork.Get("visible").AsBool(),Disabled=item.Get("locked").AsBool()});visible.Toggled+=next=>{session.Call("begin");artwork.Set("visible",next);session.Call("commit","State visibility");};Action(panel,"Import image into this state…",()=>owner.Call("import_dialog"));Action(panel,"Reset transform",()=>{if(item.Get("locked").AsBool())return;session.Call("begin");artwork.Set("position",Vector2.Zero);artwork.Set("rotation",0);artwork.Set("dimensions",baseSize);artwork.Set("opacity",1.0);artwork.Set("visible",true);state.Set("pivot",new Vector2(.5f,.5f));session.Call("commit","Reset state transform");});
    }
}
